import type { City, CountryId, CountryInfo, ProvinceId, ProvinceInfo, Scenario } from "@gs/shared";
import countriesRaw from "./countries.json";
import provincesRaw from "./provinces.json";
import scenarioRaw from "./scenario-modern.json";
import geographyRaw from "./geography.json";
import historicalRaw from "./historical-countries.json";
import { geographyFrom, type GameState, type GeographyData } from "@gs/sim";

// Generated by scripts/build-world.mjs.
export const COUNTRIES = countriesRaw as unknown as Record<CountryId, CountryInfo>;
// Countries that only exist in historical scenarios (Soviet Union, Yugoslavia, Czechoslovakia).
Object.assign(COUNTRIES, historicalRaw as unknown as Record<CountryId, CountryInfo>);
export const PROVINCES = provincesRaw as unknown as Record<ProvinceId, ProvinceInfo>;
export const MODERN_SCENARIO = scenarioRaw as unknown as Scenario;
/** Which provinces touch, which are coastal, where they are. */
export const GEOGRAPHY = geographyFrom(geographyRaw as unknown as GeographyData);

/** All known countries, sorted by name (grows when a custom world adds countries). */
export let COUNTRY_LIST: CountryInfo[] = Object.values(COUNTRIES).sort((a, b) => a.name.localeCompare(b.name));

/**
 * Make sure every country in a game has facts to show. Countries made in the world
 * editor get a simple entry (name and color; no flag or real-world facts).
 */
export function registerStateCountries(state: GameState) {
  let added = false;
  for (const c of Object.values(state.countries)) {
    const known = COUNTRIES[c.id];
    if (known && known.name === c.name) continue;
    COUNTRIES[c.id] = {
      ...(known ?? {
        id: c.id,
        officialName: null,
        kind: "sovereign",
        cca2: null,
        capital: [],
        region: null,
        subregion: null,
        areaKm2: null,
        landlocked: null,
        unMember: false,
        languages: [],
        currencies: [],
        demonym: null,
        borders: [],
        note: c.id.startsWith("R-") ? "A state that broke away during this game." : "A country from a custom world.",
        economy: null,
        incomeGroup: null,
        colorSlot: 0,
        hasFlag: false,
      }),
      name: c.name,
    } as CountryInfo;
    added = true;
  }
  if (added) COUNTRY_LIST = Object.values(COUNTRIES).sort((a, b) => a.name.localeCompare(b.name));
}

/** Countries whose land touches this one's right now (follows conquests and custom worlds). */
export function landNeighbours(state: GameState, provinceIds: ProvinceId[]): CountryId[] {
  const me = provinceIds.length ? state.provinces[provinceIds[0]!]?.owner : undefined;
  const out = new Set<CountryId>();
  for (const pid of provinceIds) {
    for (const n of GEOGRAPHY.provinces[pid]?.neighbors ?? []) {
      const o = state.provinces[n]?.owner;
      if (o && o !== me) out.add(o);
    }
  }
  return [...out].sort((a, b) => (COUNTRIES[a]?.name ?? a).localeCompare(COUNTRIES[b]?.name ?? b));
}
const PROVINCE_LIST: ProvinceInfo[] = Object.values(PROVINCES);

export const getCountry = (id: CountryId | null | undefined) => (id ? COUNTRIES[id] : undefined);
export const getProvince = (id: ProvinceId | null | undefined) => (id ? PROVINCES[id] : undefined);

export function flagUrl(c: CountryInfo): string | null {
  return c.hasFlag ? `${import.meta.env.BASE_URL}flags/${c.id}.svg` : null;
}

// Cities are loaded with the map (they're too big to bundle into the page).
let cities: City[] = [];
let citiesByProvince = new Map<ProvinceId, City[]>();
let citiesPromise: Promise<City[]> | null = null;

export function loadCities(): Promise<City[]> {
  citiesPromise ??= fetch(`${import.meta.env.BASE_URL}maps/cities.json`)
    .then((r) => {
      if (!r.ok) throw new Error(`City data request failed (${r.status})`);
      return r.json() as Promise<City[]>;
    })
    .then((list) => {
      setCities(list);
      return list;
    });
  return citiesPromise;
}

export function setCities(list: City[]) {
  cities = list;
  citiesByProvince = new Map();
  for (const c of list) {
    let l = citiesByProvince.get(c.prov);
    if (!l) citiesByProvince.set(c.prov, (l = []));
    l.push(c);
  }
}

/** Cities in a province, largest first. Empty until cities have loaded. */
export const citiesIn = (id: ProvinceId): City[] => citiesByProvince.get(id) ?? [];

export type SearchResult =
  | { kind: "country"; id: CountryId; name: string; detail: string | null; country: CountryInfo }
  | { kind: "province"; id: ProvinceId; name: string; detail: string | null }
  | { kind: "city"; city: City; name: string; detail: string | null };

/**
 * Search countries, provinces and cities. Names that start with the query
 * rank first; countries before provinces before cities; bigger places first.
 * ownerOf gives a province's current owner so results can show "Bavaria · Germany".
 */
export function search(query: string, ownerOf: (p: ProvinceId) => CountryId | undefined, limit = 10): SearchResult[] {
  const q = fold(query.trim());
  if (q.length < 2 && !/^[a-z]$/.test(q)) return [];
  const score = (name: string) => {
    const n = fold(name);
    if (n.startsWith(q)) return 0;
    if (n.split(/[\s-]/).some((w) => w.startsWith(q))) return 1;
    if (n.includes(q)) return 2;
    return -1;
  };
  const ranked: [number, number, SearchResult][] = [];
  for (const c of COUNTRY_LIST) {
    let s = score(c.name);
    if (s < 0 && c.officialName && score(c.officialName) >= 0) s = 2;
    if (s < 0 && c.id.toLowerCase() === q) s = 0;
    if (s >= 0) ranked.push([s * 3, -(c.areaKm2 ?? 0), { kind: "country", id: c.id, name: c.name, detail: null, country: c }]);
  }
  if (q.length >= 2) {
    for (const p of PROVINCE_LIST) {
      let s = score(p.name);
      for (const alt of p.localName ? [p.localName, ...p.altNames] : p.altNames) {
        const a = score(alt);
        if (a >= 0 && (s < 0 || a < s)) s = a;
      }
      if (s >= 0) ranked.push([s * 3 + 1, -p.areaKm2, { kind: "province", id: p.id, name: p.name, detail: getCountry(ownerOf(p.id))?.name ?? null }]);
    }
    for (const c of cities) {
      const s = score(c.name);
      if (s >= 0) {
        const prov = PROVINCES[c.prov];
        const country = getCountry(ownerOf(c.prov))?.name;
        ranked.push([s * 3 + 2, -c.pop, { kind: "city", city: c, name: c.name, detail: [prov?.name, country].filter(Boolean).join(" · ") }]);
      }
    }
  }
  return ranked
    .sort((a, b) => a[0] - b[0] || a[1] - b[1])
    .slice(0, limit)
    .map(([, , r]) => r);
}

/** Lowercase and strip accents so "sao" finds "São Paulo". */
const fold = (s: string) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
